--

CREATE TABLE `amicable_settlements` (
  `id` int(10) UNSIGNED NOT NULL,
  `blotter_id` int(10) UNSIGNED NOT NULL,
  `mediation_schedule_id` int(10) UNSIGNED DEFAULT NULL COMMENT 'Hearing where the settlement was signed',
