(8, 'BL-2026-001-0008', 9, 191, 85, 'Juan Ocampo', '09907473906', 'Barangay Llavac, Siniloan, Laguna', 'Marites Silverio', '09864920847', 'Barangay Acevida, Siniloan, Laguna', 'Property Damage', 'critical', '2025-07-09', '08:17:00', 'Purok 6, Siniloan, Laguna', 14.3160000, 121.2430000, 'Ang Juan Ocampo ay makipag-ugnayan sa Marites Silverio tungkol sa intimidation. Nag-uusap kami ng maingat upang malutas ang isyu.', 'refer_vawc', 'pending_review', NULL, NULL, NULL, 2, 0, '2026-02-08 08:09:52', '2026-04-21 08:09:52'),
