(10, 'BL-2026-001-0010', 6, 16, 42, 'Francisco Velasco', '09135034815', 'Barangay Acevida, Siniloan, Laguna', 'Gregorio Narciso', '09646603662', 'Barangay G. Redor (Pob.), Siniloan, Laguna', 'Verbal Abuse / Threat', 'serious', '2025-01-01', '21:41:00', 'Bonifacio Street, Siniloan, Laguna', 14.3600000, 121.3200000, 'Nagtalo ang dalawang partido dahil sa family conflict. Ang Gregorio Narciso ay umano ay lumakas habang ang Francisco Velasco ay nagsikap na mag-alaga ng kapayapaan.', 'pending', 'escalated', NULL, NULL, NULL, 2, 3, '2026-04-12 08:09:52', '2026-04-21 08:09:52'),
(11, 'BL-2026-001-0011', 9, 8, 120, 'Rosa Tolentino', '09664506526', 'Barangay Pandeno, Siniloan, Laguna', 'Andres Flores', '09649717274', 'Barangay Acevida, Siniloan, Laguna', 'Trespassing', 'critical', '2025-09-07', '08:45:00', 'Emilio Jacinto Street, Siniloan, Laguna', 14.3170000, 121.2430000, 'Nag-alala ang Rosa Tolentino dahil sa behavior ng Andres Flores. Hiniling naming tulungan ang barangay na mag-intervene.', 'refer_police', 'escalated', NULL, NULL, NULL, 2, 3, '2026-02-05 08:09:52', '2026-04-21 08:09:52'),
