INSERT INTO `sanctions_book` (`id`, `barangay_id`, `violation_type`, `violation_level`, `legal_category`, `sanction_name`, `fine_amount`, `community_hours`, `ordinance_ref`, `legal_basis`, `legal_explanation`, `description`, `is_active`, `created_at`) VALUES
(1, 1, 'Attendance', 'minor', 'kp_law', 'Failure to Appear (1st Offense)', 0.00, 0, 'KP Rule', 'Sec. 412 & 415, R.A. 7160', 'Personal appearance of parties at Lupon/Pangkat proceedings is mandatory (Sec. 415). A first unexcused absence does not yet penalize the party — the hearing is simply reset and a written warning is issued that a repeat absence carries consequences under Sec. 412 (conciliation as a precondition to filing in court).', 'First absence; subject to rescheduling with warning.', 1, '2026-04-07 01:38:42'),
(2, 1, 'Attendance', 'moderate', 'kp_law', 'Failure to Appear (2nd Offense - Complainant)', 0.00, 0, 'KP Rule', 'Sec. 412(a) & 415, R.A. 7160; Sec. 418 (analogous)', 'Where the COMPLAINANT fails to appear a second time without justifiable reason, the Lupon Chairman/Pangkat may dismiss the complaint outright. Under Sec. 412(a), prior barangay conciliation is a precondition to filing the same cause of action in court, so a complainant dismissed for repeated non-appearance is barred from refiling that specific complaint judicially.', 'Complaint may be dismissed and barred from court filing.', 1, '2026-04-07 01:38:42'),
(3, 1, 'Attendance', 'moderate', 'kp_law', 'Failure to Appear (2nd Offense - Respondent)', 0.00, 0, 'KP Rule', 'Sec. 412(b)(4), R.A. 7160', 'Where the RESPONDENT fails to appear a second time without justifiable reason, Sec. 412(b)(4) allows the complainant to go directly to court despite the general requirement of prior barangay conciliation — the Lupon issues a Certification to File Action (CFA) reflecting the respondent''s repeated non-appearance.', 'Issuance of Certification to File Action.', 1, '2026-04-07 01:38:42'),
(4, 1, 'Behavior', 'moderate', 'kp_law', 'Refusal to Participate in Mediation', 500.00, 2, 'KP Rule', 'Sec. 410(c) & 413, R.A. 7160', 'Parties are required to participate in mediation/conciliation in good faith before the Punong Barangay (Sec. 410) or the Pangkat ng Tagapagkasundo (Sec. 413). Outright refusal to engage, though physically present, may be treated by the Lupon as obstruction of the process and referred for appropriate barangay sanction under the Sangguniang Barangay''s ordinance-making power (Sec. 391).', 'Refusal to cooperate in mediation proceedings.ffff', 1, '2026-04-07 01:38:42'),
(5, 1, 'Behavior', 'moderate', 'local_ordinance', 'Disrespect to Barangay Authority', 500.00, 4, 'Barangay Ordinance 01-2020', NULL, 'Disrespect toward the Punong Barangay, Lupon members, or barangay staff while performing their Katarungang Pambarangay functions is penalized under this barangay''s own ordinance, adopted pursuant to the Sangguniang Barangay''s general ordinance-making authority (Sec. 391, R.A. 7160). This is a local penal ordinance, not a KP Law provision itself.', 'Use of offensive language or behavior during proceedings.', 1, '2026-04-07 01:38:42'),
(6, 1, 'Settlement', 'serious', 'kp_law', 'Violation of Amicable Settlement', 1000.00, 6, 'KP Rule', 'Sec. 416, R.A. 7160', 'An amicable settlement has the force and effect of a final judgment of a court upon the expiration of 10 days from the date of settlement, unless repudiated in that period (Sec. 418). Failing to comply with a final settlement''s agreed terms is treated the same as defying a court judgment and may be enforced by execution through the Lupon (within 6 months) or by ordinary court action thereafter (Sec. 417).', 'Failure to comply with agreed settlement terms.', 1, '2026-04-07 01:38:42'),
(7, 1, 'Settlement', 'minor', 'kp_law', 'Delay in Compliance of Settlement', 300.00, 2, 'KP Rule', 'Sec. 416 & 417, R.A. 7160', 'A party who is late in complying with an already-final settlement is still bound by its terms under Sec. 416. This lesser sanction covers minor delays that fall short of outright non-compliance, before the matter escalates to formal execution proceedings under Sec. 417.', 'Late compliance with settlement agreement.', 1, '2026-04-07 01:38:42'),
(8, 1, 'Public Disturbance', 'minor', 'local_ordinance', 'Noise Complaint (1st Offense)', 300.00, 2, 'Ordinance 02-2021', NULL, 'Barangay noise ordinance penalty. Adopted under the Sangguniang Barangay''s ordinance-making power (Sec. 391, R.A. 7160). This is a local penal ordinance, separate from Katarungang Pambarangay conciliation — it may still be raised as a blotter matter subject to barangay mediation before any court referral.', 'Excessive noise disturbing neighbors.', 1, '2026-04-07 01:38:42'),
(9, 1, 'Public Disturbance', 'moderate', 'local_ordinance', 'Noise Complaint (Repeat Offense)', 1000.00, 4, 'Ordinance 02-2021', NULL, 'Repeat-offense noise ordinance penalty (escalated fine/community service for a second violation). Adopted under Sec. 391, R.A. 7160.', 'Repeated excessive noise violation.', 1, '2026-04-07 01:38:42'),
(10, 1, 'Public Disturbance', 'moderate', 'local_ordinance', 'Public Drunkenness', 500.00, 3, 'Ordinance 03-2021', NULL, 'Public drunkenness / disorderly conduct penalty under local ordinance, adopted under Sec. 391, R.A. 7160. Where the conduct also involves a criminal offense (e.g. alarms and scandals under the Revised Penal Code), the barangay still refers the matter for prosecutorial action after documentation.', 'Drunk and disorderly behavior in public.', 1, '2026-04-07 01:38:42'),
(11, 1, 'Environment', 'minor', 'local_ordinance', 'Improper Garbage Disposal', 500.00, 4, 'Ordinance 04-2021', NULL, 'Improper waste disposal penalty under the barangay''s environmental/sanitation ordinance, adopted under Sec. 391, R.A. 7160, and consistent with the Ecological Solid Waste Management Act (R.A. 9003).', 'Failure to follow waste segregation rules.', 1, '2026-04-07 01:38:42'),
(12, 1, 'Environment', 'moderate', 'local_ordinance', 'Illegal Dumping', 1500.00, 6, 'Ordinance 04-2021', NULL, 'Illegal dumping penalty under the barangay''s environmental ordinance (Sec. 391, R.A. 7160), read together with R.A. 9003 (Ecological Solid Waste Management Act).', 'Dumping garbage in unauthorized areas.', 1, '2026-04-07 01:38:42'),
(13, 1, 'Curfew', 'minor', 'local_ordinance', 'Curfew Violation (Minor)', 0.00, 2, 'Ordinance 05-2021', NULL, 'Minor curfew ordinance violation. Adopted under Sec. 391, R.A. 7160. Where the person involved is a minor, the barangay coordinates with the local Council for the Protection of Children rather than imposing a fine directly on the child.', 'Minor outside beyond curfew hours.', 1, '2026-04-07 01:38:42'),
(14, 1, 'Curfew', 'moderate', 'local_ordinance', 'Curfew Violation (Repeat)', 500.00, 4, 'Ordinance 05-2021', NULL, 'Repeat curfew ordinance violation, escalated penalty. Adopted under Sec. 391, R.A. 7160.', 'Repeated curfew violation.', 1, '2026-04-07 01:38:42'),
(15, 1, 'Property', 'minor', 'kp_law', 'Light Property Damage', 1000.00, 4, 'KP Rule', 'Sec. 408 & 410, R.A. 7160', 'Property disputes between residents of the same barangay/city or municipality fall squarely within the Lupon''s conciliation jurisdiction (Sec. 408). Where the parties reach an amicable settlement covering minor property damage, non-compliance is treated under Sec. 416/417 the same as any other settlement.', 'Minor damage subject to settlement.', 1, '2026-04-07 01:38:42'),
(16, 1, 'Property', 'moderate', 'kp_law', 'Fence/Boundary Dispute Violation', 500.00, 2, 'KP Rule', 'Sec. 408 & 416, R.A. 7160', 'Boundary/fence disputes are a classic category of dispute required to first pass through Lupon conciliation (Sec. 408) before either party may go to court. This entry covers violation of a boundary settlement already reached under Sec. 416.', 'Non-compliance with agreed boundary settlement.', 1, '2026-04-07 01:38:42'),
(17, 1, 'Procedural', 'minor', 'kp_law', 'Failure to Comply with Barangay Order', 500.00, 3, 'KP Rule', 'Sec. 410 & 411, R.A. 7160', 'The Punong Barangay may issue summons and directives during mediation (Sec. 410). Ignoring a lawful barangay order issued in the course of a pending case is treated as non-cooperation with the Katarungang Pambarangay process.', 'Ignoring barangay directive.', 1, '2026-04-07 01:38:42'),
(18, 1, 'Procedural', 'moderate', 'kp_law', 'Filing Without Barangay Clearance', 0.00, 0, 'KP Rule', 'Sec. 412(a), R.A. 7160', 'Sec. 412(a) makes prior barangay conciliation a precondition to filing most disputes in court. A complaint filed in court without the required Certification to File Action (CFA) or barangay clearance is subject to dismissal by the court itself; this entry documents that procedural lapse at the barangay level.', 'Case may be dismissed in court.', 1, '2026-04-07 01:38:42'),
(19, 1, 'Community', 'minor', 'barangay_program', 'Community Service - Clean-Up Drive', 0.00, 6, 'Barangay Program', NULL, 'Voluntary or agreed community service under a barangay program, typically imposed as an alternative or supplement to a fine within an amicable settlement. Not itself a statutory penalty — its enforceability, if part of a settlement, still derives from Sec. 416, R.A. 7160.', 'Participation in barangay clean-up as corrective action.', 1, '2026-04-07 01:38:42'),
(20, 1, 'Community', 'moderate', 'barangay_program', 'Community Service - Public Maintenance', 0.00, 8, 'Barangay Program', NULL, 'Voluntary or agreed community service under a barangay program, typically imposed as an alternative or supplement to a fine within an amicable settlement. Not itself a statutory penalty — its enforceability, if part of a settlement, still derives from Sec. 416, R.A. 7160.', 'Assigned maintenance work as sanction.', 1, '2026-04-07 01:38:42');
